// lifo4_fcov: functional coverage model for the lifo4 stack block.
// Built from the approved requirement-to-plan matrix (traceability_matrix.md,
// plan-audit stage). Every bin below comes from a scenario in that matrix,
// never from the RTL's implementation.
//
// CLOSURE STATEMENT
//   Planned bins: 15. Excluded bins: 0 (the matrix waives no scenario and names
//   none the stack cannot reach).
//
//   Sampling: at every rising edge of clk, using the port values just before
//   the edge. Crosses and occupancy are sampled only with rst_n high.
//   Occupancy class from count: EMPTY = 0, MID = 1..3, FULL = 4.
//
//   bin  0  LIFO-PUSH        push alone,  stack empty
//   bin  1  LIFO-PUSH        push alone,  stack neither empty nor full
//   bin  2  LIFO-OVERFLOW    push alone,  stack full
//   bin  3  LIFO-UNDERFLOW   pop alone,   stack empty
//   bin  4  LIFO-POP         pop alone,   stack neither empty nor full
//   bin  5  LIFO-POP         pop alone,   stack full
//   bin  6  LIFO-BOTH-EMPTY  push and pop, stack empty
//   bin  7  LIFO-REPLACE     push and pop, stack neither empty nor full
//   bin  8  LIFO-REPLACE     push and pop, stack full
//   bin  9  (all)            occupancy 0
//   bin 10  (all)            occupancy 1
//   bin 11  (all)            occupancy 2
//   bin 12  (all)            occupancy 3
//   bin 13  (all)            occupancy 4
//   bin 14  LIFO-RESET       reset (rst_n low) while the stack holds a word (count >= 1)
//
//   Exclusions: none.
//
//   planned = number of tracked bins (15); holes = tracked bins not yet hit.

/* verilator lint_off UNUSEDSIGNAL */
module lifo4_fcov (
    input  logic       clk, rst_n, push, pop,
    input  logic [7:0] din, dout,
    input  logic [2:0] count,
    input  logic       empty, full, err,
    output int         planned,   // how many bins the model plans
    output int         holes      // how many of them have not been hit yet
);
/* verilator lint_on UNUSEDSIGNAL */

    localparam int NBINS = 15;

    logic [NBINS-1:0] hit = '0;

    logic occ_empty, occ_mid, occ_full;
    logic op_push, op_pop, op_both;

    assign occ_empty = (count == 3'd0);
    assign occ_mid   = (count >= 3'd1) && (count <= 3'd3);
    assign occ_full  = (count == 3'd4);

    assign op_push = push && !pop;
    assign op_pop  = pop && !push;
    assign op_both = push && pop;

    always @(posedge clk) begin
        if (rst_n) begin
            // Operation x occupancy crosses
            if (op_push && occ_empty) hit[0] <= 1'b1;
            if (op_push && occ_mid)   hit[1] <= 1'b1;
            if (op_push && occ_full)  hit[2] <= 1'b1;
            if (op_pop  && occ_empty) hit[3] <= 1'b1;
            if (op_pop  && occ_mid)   hit[4] <= 1'b1;
            if (op_pop  && occ_full)  hit[5] <= 1'b1;
            if (op_both && occ_empty) hit[6] <= 1'b1;
            if (op_both && occ_mid)   hit[7] <= 1'b1;
            if (op_both && occ_full)  hit[8] <= 1'b1;
            // Occupancy levels
            if (count == 3'd0) hit[9]  <= 1'b1;
            if (count == 3'd1) hit[10] <= 1'b1;
            if (count == 3'd2) hit[11] <= 1'b1;
            if (count == 3'd3) hit[12] <= 1'b1;
            if (count == 3'd4) hit[13] <= 1'b1;
        end else begin
            // Reset applied while the stack holds a word
            if (count >= 3'd1 && count <= 3'd4) hit[14] <= 1'b1;
        end
    end

    assign planned = NBINS;
    assign holes   = NBINS - $countones(hit);

endmodule
=== END FILE ===
